554→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
555→// Best-effort: silently ignores errors (e.g., no remote, no network).
556→func fetchTrailsBranch() {
557→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
558→	defer cancel()
559→	branchName := paths.TrailsBranchName
560→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
561→
562→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
563→	// Ensure non-interactive fetch in hook/agent contexts
564→	cmd.Stdin = nil
565→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
566→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
567→}
