569→// getTrailAuthor returns the GitHub username for the trail author.
570→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
571→func getTrailAuthor(repo *git.Repository) string {
572→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
573→	defer cancel()
574→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
575→	if output, err := cmd.Output(); err == nil {
576→		if login := strings.TrimSpace(string(output)); login != "" {
577→			return login
578→		}
579→	}
580→	name, _ := strategy.GetGitAuthorFromRepo(repo)
581→	return name
582→}
