312→// FetchAndCheckoutRemoteBranch fetches a branch from origin and creates a local tracking branch.
313→// Uses git CLI instead of go-git for fetch because go-git doesn't use credential helpers,
314→// which breaks HTTPS URLs that require authentication.
315→func FetchAndCheckoutRemoteBranch(ctx context.Context, branchName string) error {
316→	// Validate branch name before using in shell command (branchName comes from user CLI input)
317→	if err := ValidateBranchName(ctx, branchName); err != nil {
318→		return err
319→	}
320→
321→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
322→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
323→	defer cancel()
324→
325→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
326→
327→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
328→	if output, err := fetchCmd.CombinedOutput(); err != nil {
329→		if ctx.Err() == context.DeadlineExceeded {
330→			return errors.New("fetch timed out after 2 minutes")
331→		}
332→		return fmt.Errorf("failed to fetch branch from origin: %s: %w", strings.TrimSpace(string(output)), err)
333→	}
334→
335→	repo, err := openRepository(ctx)
336→	if err != nil {
337→		return fmt.Errorf("failed to open repository: %w", err)
338→	}
339→
340→	// Get the remote branch reference
341→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
342→	if err != nil {
343→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
344→	}
345→
346→	// Create local branch pointing to the same commit
347→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
348→	err = repo.Storer.SetReference(localRef)
349→	if err != nil {
350→		return fmt.Errorf("failed to create local branch: %w", err)
351→	}
352→
353→	// Checkout the new local branch
354→	return CheckoutBranch(ctx, branchName)
355→}
