217→// HasUncommittedChanges checks if there are any uncommitted changes in the repository.
218→// This includes staged changes, unstaged changes, and untracked files.
219→// Uses git CLI instead of go-git because go-git doesn't respect global gitignore
220→// (core.excludesfile) which can cause false positives for globally ignored files.
221→func HasUncommittedChanges(ctx context.Context) (bool, error) {
222→	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain")
223→	output, err := cmd.Output()
224→	if err != nil {
225→		return false, fmt.Errorf("failed to get git status: %w", err)
226→	}
227→
228→	// If output is empty, there are no changes
229→	return len(strings.TrimSpace(string(output))) > 0, nil
230→}
