286→// CheckoutBranch switches to the specified local branch or commit.
287→// Uses git CLI instead of go-git to work around go-git v5 bug where Checkout
288→// deletes untracked files (see https://github.com/go-git/go-git/issues/970).
289→// Should be switched back to go-git once we upgrade to go-git v6
290→// Returns an error if the ref doesn't exist or checkout fails.
291→func CheckoutBranch(ctx context.Context, ref string) error {
292→	if strings.HasPrefix(ref, "-") {
293→		return fmt.Errorf("checkout failed: invalid ref %q", ref)
294→	}
295→	cmd := exec.CommandContext(ctx, "git", "checkout", ref)
296→	if output, err := cmd.CombinedOutput(); err != nil {
297→		return fmt.Errorf("checkout failed: %s: %w", strings.TrimSpace(string(output)), err)
298→	}
299→	return nil
300→}
