118→// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
119→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
120→func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
121→	repo, err := OpenRepository(ctx)
122→	if err != nil {
123→		return nil, fmt.Errorf("failed to open git repository: %w", err)
124→	}
125→
126→	// Warn (once per process) if metadata branches are disconnected
127→	WarnIfMetadataDisconnected()
128→
129→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
130→	ref, err := repo.Reference(refName, true)
131→	if err != nil {
132→		//nolint:nilerr // No sessions branch yet is expected, return empty list
133→		return []CheckpointInfo{}, nil
134→	}
135→
136→	commit, err := repo.CommitObject(ref.Hash())
137→	if err != nil {
138→		return nil, fmt.Errorf("failed to get commit object: %w", err)
139→	}
140→
141→	tree, err := commit.Tree()
142→	if err != nil {
143→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
144→	}
145→
146→	var checkpoints []CheckpointInfo
147→
148→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
149→	// The tree has 2-character directories (hex buckets)
150→	for _, bucketEntry := range tree.Entries {
151→		if bucketEntry.Mode != filemode.Dir {
152→			continue
153→		}
154→		// Bucket should be 2 hex chars
155→		if len(bucketEntry.Name) != 2 {
156→			continue
157→		}
158→
159→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
160→		if treeErr != nil {
161→			continue
162→		}
163→
164→		// Each entry in the bucket is the remaining part of the checkpoint ID
165→		for _, checkpointEntry := range bucketTree.Entries {
166→			if checkpointEntry.Mode != filemode.Dir {
167→				continue
168→			}
169→
170→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
171→			if cpTreeErr != nil {
172→				continue
173→			}
174→
175→			// Reconstruct checkpoint ID: <bucket><remaining>
176→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
177→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
178→			if cpErr != nil {
179→				// Skip invalid checkpoint IDs
180→				continue
181→			}
182→
183→			info := CheckpointInfo{
184→				CheckpointID: checkpointID,
185→			}
186→
187→			// Get details from metadata file (CheckpointSummary format)
188→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
189→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
190→					var summary checkpoint.CheckpointSummary
191→					if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
192→						info.CheckpointsCount = summary.CheckpointsCount
193→						info.FilesTouched = summary.FilesTouched
194→						info.SessionCount = len(summary.Sessions)
195→
196→						// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
197→						for i, sessionPaths := range summary.Sessions {
198→							if sessionPaths.Metadata != "" {
199→								// SessionFilePaths now contains absolute paths with leading "/"
200→								// Strip the leading "/" for tree.File() which expects paths without leading slash
201→								sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
202→								if sessionFile, sErr := tree.File(sessionMetadataPath); sErr == nil {
203→									if sessionContent, scErr := sessionFile.Contents(); scErr == nil {
204→										var sessionMetadata checkpoint.CommittedMetadata
205→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
206→											info.SessionIDs = append(info.SessionIDs, sessionMetadata.SessionID)
207→											// Use first session's metadata for Agent, SessionID, CreatedAt
208→											if i == 0 {
209→												info.Agent = sessionMetadata.Agent
210→												info.SessionID = sessionMetadata.SessionID
211→												info.CreatedAt = sessionMetadata.CreatedAt
212→												info.IsTask = sessionMetadata.IsTask
213→												info.ToolUseID = sessionMetadata.ToolUseID
214→											}
215→										}
216→									}
217→								}
218→							}
219→						}
220→					}
221→				}
222→			}
223→
224→			checkpoints = append(checkpoints, info)
225→		}
226→	}
227→
228→	// Sort by time (most recent first)
229→	sort.Slice(checkpoints, func(i, j int) bool {
230→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
231→	})
232→
233→	return checkpoints, nil
234→}
