 18→// openRepository opens the git repository with linked worktree support enabled.
 19→// This is a convenience wrapper around strategy.OpenRepository() for use in the CLI package.
 20→func openRepository(ctx context.Context) (*git.Repository, error) {
 21→	repo, err := strategy.OpenRepository(ctx)
 22→	if err != nil {
 23→		return nil, fmt.Errorf("failed to open repository: %w", err)
 24→	}
 25→	return repo, nil
 26→}
 27→
 28→// GitAuthor represents the git user configuration
 29→type GitAuthor struct {
 30→	Name  string
 31→	Email string
 32→}
 33→
 34→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
 35→// It checks local config first, then falls back to global config.
 36→// If go-git can't find the config, it falls back to using the git command.
 37→// Returns fallback defaults if no user is configured anywhere.
 38→func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
 39→	repo, err := openRepository(ctx)
 40→	if err != nil {
 41→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 42→	}
 43→
 44→	name, email := strategy.GetGitAuthorFromRepo(repo)
 45→
 46→	// If go-git returned defaults, try using git command as fallback
 47→	// This handles cases where go-git can't find the config (e.g., different HOME paths,
 48→	// non-standard config locations, or environment issues in hook contexts)
 49→	if name == "Unknown" {
 50→		if gitName := getGitConfigValue(ctx, "user.name"); gitName != "" {
 51→			name = gitName
 52→		}
 53→	}
 54→	if email == "unknown@local" {
 55→		if gitEmail := getGitConfigValue(ctx, "user.email"); gitEmail != "" {
 56→			email = gitEmail
 57→		}
 58→	}
 59→
 60→	return &GitAuthor{
 61→		Name:  name,
 62→		Email: email,
 63→	}, nil
 64→}
 65→
 66→// getGitConfigValue retrieves a git config value using the git command.
 67→// Returns empty string if the value is not set or on error.
 68→func getGitConfigValue(ctx context.Context, key string) string {
 69→	cmd := exec.CommandContext(ctx, "git", "config", "--get", key)
 70→	output, err := cmd.Output()
 71→	if err != nil {
 72→		return ""
 73→	}
 74→	return strings.TrimSpace(string(output))
 75→}
 76→
 77→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 78→// It determines the default branch by:
 79→// 1. Checking the remote origin's HEAD reference
 80→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 81→// Returns (isDefault, branchName, error)
 82→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 83→	repo, err := openRepository(ctx)
 84→	if err != nil {
 85→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 86→	}
 87→
 88→	// Get current branch
 89→	head, err := repo.Head()
 90→	if err != nil {
 91→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 92→	}
 93→
 94→	if !head.Name().IsBranch() {
 95→		// Detached HEAD - not on any branch
 96→		return false, "", nil
 97→	}
 98→
 99→	currentBranch := head.Name().Short()
100→
101→	// Try to get default branch from remote origin's HEAD
102→	defaultBranch := getDefaultBranchFromRemote(repo)
103→
104→	// If we couldn't determine from remote, use common defaults
105→	if defaultBranch == "" {
106→		// Check if current branch is a common default name
107→		if currentBranch == "main" || currentBranch == "master" {
108→			return true, currentBranch, nil
109→		}
110→		return false, currentBranch, nil
111→	}
112→
113→	return currentBranch == defaultBranch, currentBranch, nil
114→}
115→
116→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
117→// Returns empty string if unable to determine.
118→func getDefaultBranchFromRemote(repo *git.Repository) string {
119→	// Try to get the symbolic reference for origin/HEAD
120→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
121→	if err == nil && ref != nil {
122→		// ref.Target() gives us something like "refs/remotes/origin/main"
123→		target := ref.Target().String()
124→		if strings.HasPrefix(target, "refs/remotes/origin/") {
125→			return strings.TrimPrefix(target, "refs/remotes/origin/")
126→		}
127→	}
128→
129→	// Fallback: check if origin/main or origin/master exists
130→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
131→		return "main"
132→	}
133→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
134→		return "master"
135→	}
136→
137→	return ""
138→}
139→
140→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
141→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
142→// skip the operation to avoid polluting main/master history.
143→// If the branch cannot be determined, returns (false, "") to allow the operation.
144→func ShouldSkipOnDefaultBranch(ctx context.Context) (bool, string) {
145→	isDefault, branchName, err := IsOnDefaultBranch(ctx)
146→	if err != nil {
147→		// If we can't determine, allow the operation
148→		return false, ""
149→	}
150→	return isDefault, branchName
151→}
152→
153→// GetCurrentBranch returns the name of the current branch.
154→// Returns an error if in detached HEAD state or if not in a git repository.
155→func GetCurrentBranch(ctx context.Context) (string, error) {
156→	repo, err := openRepository(ctx)
157→	if err != nil {
158→		return "", fmt.Errorf("failed to open git repository: %w", err)
159→	}
160→
161→	head, err := repo.Head()
162→	if err != nil {
163→		return "", fmt.Errorf("failed to get HEAD: %w", err)
164→	}
165→
166→	if !head.Name().IsBranch() {
167→		return "", errors.New("not on a branch (detached HEAD)")
168→	}
169→
170→	return head.Name().Short(), nil
171→}
172→
173→// GetMergeBase finds the common ancestor (merge-base) between two branches.
174→// Returns the hash of the merge-base commit.
175→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
176→	repo, err := openRepository(ctx)
177→	if err != nil {
178→		return nil, fmt.Errorf("failed to open git repository: %w", err)
179→	}
180→
181→	// Resolve branch references
182→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
183→	if err != nil {
184→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
185→	}
186→
187→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
188→	if err != nil {
189→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
190→	}
191→
192→	// Get commit objects
193→	commit1, err := repo.CommitObject(ref1.Hash())
194→	if err != nil {
195→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
196→	}
197→
198→	commit2, err := repo.CommitObject(ref2.Hash())
199→	if err != nil {
200→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
201→	}
202→
203→	// Find common ancestor
204→	mergeBase, err := commit1.MergeBase(commit2)
205→	if err != nil {
206→		return nil, fmt.Errorf("failed to find merge base: %w", err)
207→	}
208→
209→	if len(mergeBase) == 0 {
210→		return nil, errors.New("no common ancestor found")
211→	}
212→
213→	hash := mergeBase[0].Hash
214→	return &hash, nil
215→}
216→
217→// HasUncommittedChanges checks if there are any uncommitted changes in the repository.
218→// This includes staged changes, unstaged changes, and untracked files.
219→// Uses git CLI instead of go-git because go-git doesn't respect global gitignore
220→// (core.excludesfile) which can cause false positives for globally ignored files.
221→func HasUncommittedChanges(ctx context.Context) (bool, error) {
222→	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain")
223→	output, err := cmd.Output()
224→	if err != nil {
225→		return false, fmt.Errorf("failed to get git status: %w", err)
226→	}
227→
228→	// If output is empty, there are no changes
229→	return len(strings.TrimSpace(string(output))) > 0, nil
230→}
231→
232→// findNewUntrackedFiles finds files that are newly untracked (not in pre-existing list)
233→func findNewUntrackedFiles(current, preExisting []string) []string {
234→	preExistingSet := make(map[string]bool)
235→	for _, file := range preExisting {
236→		preExistingSet[file] = true
237→	}
238→
239→	var newFiles []string
240→	for _, file := range current {
241→		if !preExistingSet[file] {
242→			newFiles = append(newFiles, file)
243→		}
244→	}
245→	return newFiles
246→}
247→
