 84→// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
 85→// Returns true if target can reach commit by following parent links.
 86→// Limits search to MaxCommitTraversalDepth commits to avoid excessive traversal.
 87→func IsAncestorOf(ctx context.Context, repo *git.Repository, commit, target plumbing.Hash) bool {
 88→	if commit == target {
 89→		return true
 90→	}
 91→
 92→	iter, err := repo.Log(&git.LogOptions{From: target})
 93→	if err != nil {
 94→		return false
 95→	}
 96→	defer iter.Close()
 97→
 98→	found := false
 99→	count := 0
100→	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
101→		if err := ctx.Err(); err != nil {
102→			return err //nolint:wrapcheck // Propagating context cancellation
103→		}
104→		count++
105→		if count > MaxCommitTraversalDepth {
106→			return errStop
107→		}
108→		if c.Hash == commit {
109→			found = true
110→			return errStop
111→		}
112→		return nil
113→	})
114→
115→	return found
116→}
