				settings.StrategyOptions[k] = v
			}
		}
	}

	// Override telemetry if present
	if telemetryRaw, ok := raw["telemetry"]; ok {
		var t bool
		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
			return fmt.Errorf("parsing telemetry field: %w", err)
		}
		settings.Telemetry = &t
	}

	// Override commit_linking if present and non-empty
	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
		var cl string
		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
			return fmt.Errorf("parsing commit_linking field: %w", err)
		}
		if cl != "" {
			switch cl {
			case CommitLinkingAlways, CommitLinkingPrompt:
				settings.CommitLinking = cl
			default:
				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
			}
		}
	}

	// Override external_agents if present
	if externalAgentsRaw, ok := raw["external_agents"]; ok {
		var ea bool
		if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
			return fmt.Errorf("parsing external_agents field: %w", err)
		}
		settings.ExternalAgents = ea
	}

	return nil
}

// IsSetUp returns true if Entire has been set up in the current repository.
// This checks if .entire/settings.json exists.
// Use this to avoid creating files/directories in repos where Entire was never enabled.
func IsSetUp(ctx context.Context) bool {
	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
	if err != nil {
		return false
	}
	_, err = os.Stat(settingsFileAbs)
	return err == nil
}

// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
// This checks if .entire/settings.json exists AND has enabled: true.
// Use this for hooks that should be no-ops when Entire is not active.
func IsSetUpAndEnabled(ctx context.Context) bool {
	if !IsSetUp(ctx) {
		return false
	}
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.Enabled
}

// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsSummarizeEnabled(ctx context.Context) bool {
	settings, err := Load(ctx)
	if err != nil {
		return false
	}
	return settings.IsSummarizeEnabled()
}

// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
func (s *EntireSettings) IsSummarizeEnabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
	if !ok {
		return false
	}
	enabled, ok := summarizeOpts["enabled"].(bool)
	if !ok {
		return false
	}
	return enabled
}

// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
// Returns true if push_sessions is explicitly set to false.
func (s *EntireSettings) IsPushSessionsDisabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	val, exists := s.StrategyOptions["push_sessions"]
	if !exists {
		return false
	}
	if boolVal, ok := val.(bool); ok {
		return !boolVal // disabled = !push_sessions
	}
	return false
}

// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsExternalAgentsEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.ExternalAgents
}

// Save saves the settings to .entire/settings.json.
func Save(ctx context.Context, settings *EntireSettings) error {
	return saveToFile(ctx, settings, EntireSettingsFile)
}

// SaveLocal saves the settings to .entire/settings.local.json.
func SaveLocal(ctx context.Context, settings *EntireSettings) error {
	return saveToFile(ctx, settings, EntireSettingsLocalFile)
}

// saveToFile saves settings to the specified file path.
func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
	// Get absolute path for the file
	filePathAbs, err := paths.AbsPath(ctx, filePath)
	if err != nil {
		filePathAbs = filePath // Fallback to relative
	}

	// Ensure directory exists
	dir := filepath.Dir(filePathAbs)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("creating settings directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling settings: %w", err)
	}

	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
		return fmt.Errorf("writing settings file: %w", err)
	}
	return nil
}

package gitprovider

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
)

// ProviderName identifies a git provider implementation.
type ProviderName string

const (
	// ProviderGoGit selects the go-git library implementation.
	ProviderGoGit ProviderName = "go-git"
	// ProviderCLI selects the git CLI implementation.
	ProviderCLI ProviderName = "cli"
)

// CategoryConfig maps each provider category to an implementation name.
// Any zero-value entry falls back to the category default.
type CategoryConfig struct {
	References ProviderName `json:"references,omitempty"`
	Objects    ProviderName `json:"objects,omitempty"`
	Worktree   ProviderName `json:"worktree,omitempty"`
	Remote     ProviderName `json:"remote,omitempty"`
	Config     ProviderName `json:"config,omitempty"`
	Diff       ProviderName `json:"diff,omitempty"`
}

// DefaultConfig returns the recommended defaults:
//   - go-git for references and objects (fast, in-process)
//   - CLI for worktree, remote, config, diff (correct, uses credential helpers)
func DefaultConfig() CategoryConfig {
	return CategoryConfig{
		References: ProviderGoGit,
		Objects:    ProviderGoGit,
		Worktree:   ProviderCLI,
		Remote:     ProviderCLI,
		Config:     ProviderCLI,
		Diff:       ProviderCLI,
	}
}

// Open creates a Repository using the given category configuration.
// It opens a go-git repository if any category requires it, and creates
// a CLI provider for categories that need it.
func Open(ctx context.Context, cfg CategoryConfig) (Repository, error) {
	cfg = withDefaults(cfg)

	needsGoGit := cfg.References == ProviderGoGit ||
		cfg.Objects == ProviderGoGit ||
		cfg.Worktree == ProviderGoGit ||
		cfg.Remote == ProviderGoGit ||
		cfg.Config == ProviderGoGit ||
		cfg.Diff == ProviderGoGit

	needsCLI := cfg.References == ProviderCLI ||
		cfg.Objects == ProviderCLI ||
		cfg.Worktree == ProviderCLI ||
		cfg.Remote == ProviderCLI ||
		cfg.Config == ProviderCLI ||
		cfg.Diff == ProviderCLI

	var goGitProvider *GoGit
	var cliProvider *CLI

	if needsGoGit {
		repo, err := openGoGitRepo(ctx)
		if err != nil {
			return nil, fmt.Errorf("opening go-git repository: %w", err)
		}
		goGitProvider = NewGoGit(repo)
	}

	if needsCLI {
		cliProvider = NewCLI("")
	}

	return NewComposite(
		WithReferenceProvider(pickRef(cfg.References, goGitProvider, cliProvider)),
		WithObjectProvider(pickObj(cfg.Objects, goGitProvider, cliProvider)),
		WithWorktreeProvider(pickWorktree(cfg.Worktree, goGitProvider, cliProvider)),
		WithRemoteProvider(pickRemote(cfg.Remote, goGitProvider, cliProvider)),
		WithConfigProvider(pickConfig(cfg.Config, goGitProvider, cliProvider)),
		WithDiffProvider(pickDiff(cfg.Diff, goGitProvider, cliProvider)),
	), nil
}

// OpenDefault creates a Repository with the default configuration.
func OpenDefault(ctx context.Context) (Repository, error) {
	return Open(ctx, DefaultConfig())
}

// openGoGitRepo opens a go-git repository from the worktree root.
func openGoGitRepo(ctx context.Context) (*git.Repository, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "."
	}
	repo, err := git.PlainOpen(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("failed to open repository at %s: %w", repoRoot, err)
	}
	return repo, nil
}

// withDefaults fills in zero-value fields with sensible defaults.
func withDefaults(cfg CategoryConfig) CategoryConfig {
	defaults := DefaultConfig()
	if cfg.References == "" {
		cfg.References = defaults.References
	}
	if cfg.Objects == "" {
		cfg.Objects = defaults.Objects
	}
	if cfg.Worktree == "" {
		cfg.Worktree = defaults.Worktree
	}
	if cfg.Remote == "" {
		cfg.Remote = defaults.Remote
	}
	if cfg.Config == "" {
		cfg.Config = defaults.Config
	}
	if cfg.Diff == "" {
		cfg.Diff = defaults.Diff
	}
	return cfg
}

func pickRef(name ProviderName, goGit *GoGit, cli *CLI) ReferenceProvider {
	if name == ProviderCLI {
		return cli
	}
	return goGit
}

func pickObj(name ProviderName, goGit *GoGit, cli *CLI) ObjectProvider {
	if name == ProviderCLI {
		return cli
	}
	return goGit
}

func pickWorktree(name ProviderName, goGit *GoGit, cli *CLI) WorktreeProvider {
	if name == ProviderCLI {
		return cli
	}
	return goGit
}

func pickRemote(name ProviderName, goGit *GoGit, cli *CLI) RemoteProvider {
	if name == ProviderCLI {
		return cli
	}
	return goGit
}

func pickConfig(name ProviderName, goGit *GoGit, cli *CLI) ConfigProvider {
	if name == ProviderCLI {
		return cli
	}
	return goGit
}

func pickDiff(name ProviderName, goGit *GoGit, cli *CLI) DiffProvider {
	if name == ProviderCLI {
		return cli
	}
	return goGit
}

