	return c.refs.SetReference(ref)
}

func (c *Composite) ListBranches() (storer.ReferenceIter, error) {
	return c.refs.ListBranches()
}

func (c *Composite) ListReferences() (storer.ReferenceIter, error) {
	return c.refs.ListReferences()
}

