775→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
776→// Works correctly from any subdirectory within the repository.
777→func EnsureEntireGitignore(ctx context.Context) error {
778→	// Get absolute path for the gitignore file
779→	gitignoreAbs, err := paths.AbsPath(ctx, entireGitignore)
780→	if err != nil {
781→		gitignoreAbs = entireGitignore // Fallback to relative
782→	}
783→
784→	// Read existing content
785→	var content string
786→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
787→		content = string(data)
788→	}
789→
790→	// All entries that should be in .entire/.gitignore
791→	requiredEntries := []string{
792→		"tmp/",
793→		"settings.local.json",
794→		"metadata/",
795→		"logs/",
796→	}
797→
798→	// Track what needs to be added
799→	var toAdd []string
800→	for _, entry := range requiredEntries {
801→		if !strings.Contains(content, entry) {
802→			toAdd = append(toAdd, entry)
803→		}
804→	}
805→
806→	// Nothing to add
807→	if len(toAdd) == 0 {
808→		return nil
809→	}
810→
811→	// Ensure .entire directory exists
812→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
813→		return fmt.Errorf("failed to create .entire directory: %w", err)
814→	}
815→
816→	// Append missing entries to gitignore
817→	var sb strings.Builder
818→	for _, entry := range toAdd {
819→		sb.WriteString(entry + "\n")
820→	}
821→	content += sb.String()
822→
823→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
824→		return fmt.Errorf("failed to write gitignore: %w", err)
825→	}
826→	return nil
827→}
