1204→	cmd := exec.CommandContext(ctx, "git", "ls-files", "--others", "--exclude-standard", "-z")
1205→	cmd.Dir = repoRoot
1206→	output, err := cmd.Output()
1207→	if err != nil {
1208→		var exitErr *exec.ExitError
1209→		if errors.As(err, &exitErr) {
1210→			return nil, fmt.Errorf("git ls-files failed: %s: %w", strings.TrimSpace(string(exitErr.Stderr)), err)
1211→		}
1212→		return nil, fmt.Errorf("git ls-files failed: %w", err)
1213→	}
1214→
1215→	raw := string(output)
1216→	if raw == "" {
1217→		return nil, nil
1218→	}
1219→
1220→	var files []string
1221→	for _, f := range strings.Split(raw, "\x00") {
1222→		// Defense-in-depth: filter protected paths even though --exclude-standard should already handle them
1223→		if f != "" && !isProtectedPath(f) {
