729→	// Modified/new files → create blobs from disk
730→	for _, file := range modifiedFiles {
731→		absPath := filepath.Join(repoRoot, file)
732→		if !fileExists(absPath) {
733→			// File disappeared since detection — treat as deletion
734→			changes = append(changes, TreeChange{Path: file, Entry: nil})
735→			continue
736→		}
737→
738→		blobHash, mode, blobErr := createBlobFromFile(s.repo, absPath)
739→		if blobErr != nil {
740→			// Skip files that can't be staged (may have been deleted since detection)
741→			continue
742→		}
743→
744→		changes = append(changes, TreeChange{
745→			Path: file,
746→			Entry: &object.TreeEntry{
747→				Mode: mode,
748→				Hash: blobHash,
749→			},
750→		})
751→	}
752→
753→	// Metadata directory files
754→	if metadataDir != "" && metadataDirAbs != "" {
755→		metaChanges, metaErr := addDirectoryToChanges(s.repo, metadataDirAbs, metadataDir)
756→		if metaErr != nil {
757→			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", metaErr)
758→		}
759→		changes = append(changes, metaChanges...)
760→	}
761→
762→	return ApplyTreeChanges(s.repo, baseTreeHash, changes)
763→}
