 856→// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
 857→func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
 858→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
 859→		if err != nil {
 860→			return err
 861→		}
 862→
 863→		// Skip symlinks to prevent reading files outside the metadata directory.
 864→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
 865→		// then be captured in the checkpoint and stored in git history.
 866→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
 867→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
 868→		// This check MUST come before IsDir() because Walk follows symlinked
 869→		// directories and would recurse into them otherwise.
 870→		linfo, lstatErr := os.Lstat(path)
 871→		if lstatErr != nil {
 872→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
 873→		}
 874→		if linfo.Mode()&os.ModeSymlink != 0 {
 875→			if info.IsDir() {
 876→				return filepath.SkipDir
 877→			}
 878→			return nil
 879→		}
 880→
 881→		if info.IsDir() {
 882→			return nil
 883→		}
 884→
 885→		// Calculate relative path within the directory, then join with dirPathRel for tree entry
 886→		relWithinDir, err := filepath.Rel(dirPathAbs, path)
 887→		if err != nil {
 888→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
 889→		}
 890→
 891→		// Prevent path traversal via symlinks pointing outside the metadata dir
 892→		if strings.HasPrefix(relWithinDir, "..") {
 893→			return fmt.Errorf("path traversal detected: %s", relWithinDir)
 894→		}
 895→
 896→		treePath := filepath.ToSlash(filepath.Join(dirPathRel, relWithinDir))
 897→
 898→		blobHash, mode, err := createRedactedBlobFromFile(repo, path, treePath)
 899→		if err != nil {
 900→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
 901→		}
 902→		entries[treePath] = object.TreeEntry{
 903→			Name: treePath,
 904→			Mode: mode,
 905→			Hash: blobHash,
 906→		}
 907→		return nil
 908→	})
 909→	if err != nil {
 910→		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
 911→	}
 912→	return nil
 913→}
