 973→// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
 974→// Exported for use by strategy package (push_common.go, session_test.go)
 975→func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
 976→	// Build a tree structure
 977→	root := &treeNode{
 978→		entries: make(map[string]*treeNode),
 979→		files:   []object.TreeEntry{},
 980→	}
