1325→// CreateBlobFromContent creates a blob object from in-memory content.
1326→// Exported for use by strategy package (session_test.go)
1327→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1328→	obj := repo.Storer.NewEncodedObject()
1329→	obj.SetType(plumbing.BlobObject)
1330→	obj.SetSize(int64(len(content)))
1331→
1332→	writer, err := obj.Writer()
1333→	if err != nil {
1334→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1335→	}
1336→
1337→	_, err = writer.Write(content)
1338→	if err != nil {
1339→		_ = writer.Close()
1340→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1341→	}
1342→	if err := writer.Close(); err != nil {
1343→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1344→	}
1345→
1346→	hash, err := repo.Storer.SetEncodedObject(obj)
1347→	if err != nil {
1348→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1349→	}
1350→	return hash, nil
1351→}
