1353→// copyMetadataDir copies all files from a directory to the checkpoint path.
1354→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1355→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1356→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1357→		if err != nil {
1358→			return err
1359→		}
1360→
1361→		// Skip symlinks to prevent reading files outside the metadata directory.
1362→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1363→		// then be captured in the checkpoint and stored in git history.
1364→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
1365→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
1366→		// This check MUST come before IsDir() because Walk follows symlinked
1367→		// directories and would recurse into them otherwise.
1368→		linfo, lstatErr := os.Lstat(path)
1369→		if lstatErr != nil {
1370→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
1371→		}
1372→		if linfo.Mode()&os.ModeSymlink != 0 {
1373→			if info.IsDir() {
1374→				return filepath.SkipDir
1375→			}
1376→			return nil
1377→		}
1378→
1379→		if info.IsDir() {
1380→			return nil
1381→		}
1382→
1383→		// Get relative path within metadata dir
1384→		relPath, err := filepath.Rel(metadataDir, path)
1385→		if err != nil {
1386→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1387→		}
1388→
1389→		// Prevent path traversal via symlinks pointing outside the metadata dir
1390→		if strings.HasPrefix(relPath, "..") {
1391→			return fmt.Errorf("path traversal detected: %s", relPath)
1392→		}
1393→
1394→		// Create blob from file with secrets redaction
1395→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1396→		if err != nil {
1397→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1398→		}
1399→
1400→		// Store at checkpoint path (use forward slashes for git tree compatibility on Windows)
1401→		fullPath := basePath + filepath.ToSlash(relPath)
1402→		entries[fullPath] = object.TreeEntry{
1403→			Name: fullPath,
1404→			Mode: mode,
1405→			Hash: blobHash,
1406→		}
1407→
1408→		return nil
1409→	})
1410→	if err != nil {
1411→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1412→	}
1413→	return nil
1414→}
1415→
1416→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1417→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1418→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1419→	info, err := os.Stat(filePath)
1420→	if err != nil {
1421→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1422→	}
1423→
1424→	mode := filemode.Regular
1425→	if info.Mode()&0o111 != 0 {
1426→		mode = filemode.Executable
1427→	}
1428→
1429→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1430→	if err != nil {
1431→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1432→	}
1433→
1434→	// Skip redaction for binary files — they can't contain text secrets and
1435→	// running string replacement on them would corrupt the data.
1436→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1437→	if binErr != nil || isBin {
1438→		hash, err := CreateBlobFromContent(repo, content)
1439→		if err != nil {
1440→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1441→		}
1442→		return hash, mode, nil
1443→	}
1444→
1445→	if strings.HasSuffix(treePath, ".jsonl") {
1446→		redacted, jsonlErr := redact.JSONLBytes(content)
1447→		if jsonlErr != nil {
1448→			redacted = redact.Bytes(content)
1449→		}
1450→		content = redacted
1451→	} else {
1452→		content = redact.Bytes(content)
1453→	}
1454→
1455→	hash, err := CreateBlobFromContent(repo, content)
1456→	if err != nil {
1457→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1458→	}
1459→	return hash, mode, nil
1460→}
