1616→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
1617→// Finds the commit whose subject matches "Checkpoint: <id>" and returns its author.
1618→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
1619→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
1620→	if err := ctx.Err(); err != nil {
1621→		return Author{}, err //nolint:wrapcheck // Propagating context cancellation
1622→	}
1623→
1624→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1625→	ref, err := s.repo.Reference(refName, true)
1626→	if err != nil {
1627→		return Author{}, nil
1628→	}
1629→
1630→	// Search for the commit whose subject matches "Checkpoint: <id>"
1631→	targetSubject := "Checkpoint: " + checkpointID.String()
1632→
1633→	iter, err := s.repo.Log(&git.LogOptions{
1634→		From:  ref.Hash(),
1635→		Order: git.LogOrderCommitterTime,
1636→	})
1637→	if err != nil {
1638→		return Author{}, nil
1639→	}
1640→	defer iter.Close()
1641→
1642→	var author Author
1643→	err = iter.ForEach(func(c *object.Commit) error {
1644→		if err := ctx.Err(); err != nil {
1645→			return err //nolint:wrapcheck // Propagating context cancellation
1646→		}
1647→		subject := strings.SplitN(c.Message, "\n", 2)[0]
1648→		if subject == targetSubject {
1649→			author = Author{
1650→				Name:  c.Author.Name,
1651→				Email: c.Author.Email,
1652→			}
1653→			return errStopIteration
1654→		}
1655→		return nil
1656→	})
1657→
1658→	if err != nil && !errors.Is(err, errStopIteration) {
1659→		return Author{}, nil
1660→	}
1661→
1662→	return author, nil
1663→}
