 774→// FlattenTree recursively flattens a tree into a map of full paths to entries.
 775→func FlattenTree(repo gitprovider.ObjectProvider, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
 776→	for _, entry := range tree.Entries {
 777→		fullPath := entry.Name
 778→		if prefix != "" {
 779→			fullPath = prefix + "/" + entry.Name
 780→		}
 781→
 782→		if entry.Mode == filemode.Dir {
 783→			// Recurse into subtree
 784→			subtree, err := repo.TreeObject(entry.Hash)
 785→			if err != nil {
 786→				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
 787→			}
 788→			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
 789→				return err
 790→			}
 791→		} else {
 792→			entries[fullPath] = object.TreeEntry{
 793→				Name: fullPath,
 794→				Mode: entry.Mode,
 795→				Hash: entry.Hash,
 796→			}
 797→		}
 798→	}
 799→	return nil
 800→}
