 808→// createBlobFromFile creates a blob object from a file in the working directory.
 809→func createBlobFromFile(repo gitprovider.ObjectProvider, filePath string) (plumbing.Hash, filemode.FileMode, error) {
 810→	info, err := os.Stat(filePath)
 811→	if err != nil {
 812→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
 813→	}
 814→
 815→	// Determine file mode
 816→	mode := filemode.Regular
 817→	if info.Mode()&0o111 != 0 {
 818→		mode = filemode.Executable
 819→	}
 820→	if info.Mode()&os.ModeSymlink != 0 {
 821→		mode = filemode.Symlink
 822→	}
 823→
 824→	// Read file contents
 825→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
 826→	if err != nil {
 827→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
 828→	}
 829→
 830→	// Create blob object
 831→	obj := repo.Storer().NewEncodedObject()
 832→	obj.SetType(plumbing.BlobObject)
 833→	obj.SetSize(int64(len(content)))
 834→
 835→	writer, err := obj.Writer()
 836→	if err != nil {
 837→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
 838→	}
 839→
 840→	_, err = writer.Write(content)
 841→	if err != nil {
 842→		_ = writer.Close()
 843→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
 844→	}
 845→	if err := writer.Close(); err != nil {
 846→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
 847→	}
 848→
 849→	hash, err := repo.Storer().SetEncodedObject(obj)
 850→	if err != nil {
 851→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
 852→	}
 853→
 854→	return hash, mode, nil
 855→}
 856→
 857→// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
 858→func addDirectoryToEntriesWithAbsPath(repo gitprovider.ObjectProvider, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
 859→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
 860→		if err != nil {
 861→			return err
 862→		}
 863→
 864→		// Skip symlinks to prevent reading files outside the metadata directory.
 865→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
 866→		// then be captured in the checkpoint and stored in git history.
 867→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
 868→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
