  1→package cli
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"strings"
  8→	"time"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/gitprovider"
 11→	"github.com/entireio/cli/cmd/entire/cli/paths"
 12→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 13→
 14→	"github.com/go-git/go-git/v6"
 15→	"github.com/go-git/go-git/v6/plumbing"
 16→)
 17→
 18→// openRepository opens the git repository with linked worktree support enabled.
 19→// This is a convenience wrapper around strategy.OpenRepository() for use in the CLI package.
 20→// Kept for backward compatibility with tests and code that still needs *git.Repository.
 21→func openRepository(ctx context.Context) (*git.Repository, error) {
 22→	repo, err := strategy.OpenRepository(ctx)
 23→	if err != nil {
 24→		return nil, fmt.Errorf("failed to open repository: %w", err)
 25→	}
 26→	return repo, nil
 27→}
 28→
 29→// openProvider opens a gitprovider.Repository using the default configuration.
 30→// This is the preferred way to access git operations in the CLI package.
 31→func openProvider(ctx context.Context) (gitprovider.Repository, error) {
 32→	return gitprovider.OpenDefault(ctx)
 33→}
 34→
 35→// GitAuthor represents the git user configuration
 36→type GitAuthor struct {
 37→	Name  string
 38→	Email string
 39→}
 40→
 41→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
 42→// Uses gitprovider.Repository.ConfigValue to read git config values.
 43→// Returns fallback defaults if no user is configured anywhere.
 44→func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
 45→	repo, err := openProvider(ctx)
 46→	if err != nil {
 47→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 48→	}
 49→
 50→	name, _ := repo.ConfigValue(ctx, "user.name")
 51→	if name == "" {
 52→		name = "Unknown"
 53→	}
 54→
 55→	email, _ := repo.ConfigValue(ctx, "user.email")
 56→	if email == "" {
 57→		email = "unknown@local"
 58→	}
 59→
 60→	return &GitAuthor{
 61→		Name:  name,
 62→		Email: email,
 63→	}, nil
 64→}
 65→
 66→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 67→// It determines the default branch by:
 68→// 1. Checking the remote origin's HEAD reference
 69→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 70→// Returns (isDefault, branchName, error)
 71→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 72→	repo, err := openProvider(ctx)
 73→	if err != nil {
 74→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 75→	}
 76→
 77→	// Get current branch
 78→	head, err := repo.Head()
 79→	if err != nil {
 80→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 81→	}
 82→
 83→	if !head.Name().IsBranch() {
 84→		// Detached HEAD - not on any branch
 85→		return false, "", nil
 86→	}
 87→
 88→	currentBranch := head.Name().Short()
 89→
 90→	// Try to get default branch from remote origin's HEAD
 91→	defaultBranch := getDefaultBranchFromRemote(repo)
 92→
 93→	// If we couldn't determine from remote, use common defaults
 94→	if defaultBranch == "" {
 95→		// Check if current branch is a common default name
 96→		if currentBranch == "main" || currentBranch == "master" {
 97→			return true, currentBranch, nil
 98→		}
 99→		return false, currentBranch, nil
100→	}
101→
102→	return currentBranch == defaultBranch, currentBranch, nil
103→}
104→
105→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
106→// Returns empty string if unable to determine.
107→func getDefaultBranchFromRemote(repo gitprovider.Repository) string {
108→	// Try to get the symbolic reference for origin/HEAD
109→	ref, err := repo.GetReference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
110→	if err == nil && ref != nil {
111→		// ref.Target() gives us something like "refs/remotes/origin/main"
112→		target := ref.Target().String()
113→		if strings.HasPrefix(target, "refs/remotes/origin/") {
114→			return strings.TrimPrefix(target, "refs/remotes/origin/")
115→		}
116→	}
117→
118→	// Fallback: check if origin/main or origin/master exists
119→	if _, err := repo.GetReference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
120→		return "main"
121→	}
122→	if _, err := repo.GetReference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
123→		return "master"
124→	}
125→
126→	return ""
127→}
128→
129→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
130→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
131→// skip the operation to avoid polluting main/master history.
132→// If the branch cannot be determined, returns (false, "") to allow the operation.
133→func ShouldSkipOnDefaultBranch(ctx context.Context) (bool, string) {
134→	isDefault, branchName, err := IsOnDefaultBranch(ctx)
135→	if err != nil {
136→		// If we can't determine, allow the operation
137→		return false, ""
138→	}
139→	return isDefault, branchName
140→}
141→
142→// GetCurrentBranch returns the name of the current branch.
143→// Returns an error if in detached HEAD state or if not in a git repository.
144→func GetCurrentBranch(ctx context.Context) (string, error) {
145→	repo, err := openProvider(ctx)
146→	if err != nil {
147→		return "", fmt.Errorf("failed to open git repository: %w", err)
148→	}
149→
150→	head, err := repo.Head()
151→	if err != nil {
152→		return "", fmt.Errorf("failed to get HEAD: %w", err)
153→	}
154→
155→	if !head.Name().IsBranch() {
156→		return "", errors.New("not on a branch (detached HEAD)")
157→	}
158→
159→	return head.Name().Short(), nil
160→}
161→
162→// GetMergeBase finds the common ancestor (merge-base) between two branches.
163→// Returns the hash of the merge-base commit.
164→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
165→	repo, err := openProvider(ctx)
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to open git repository: %w", err)
168→	}
169→
170→	// Resolve branch references
171→	ref1, err := repo.GetReference(plumbing.NewBranchReferenceName(branch1), true)
172→	if err != nil {
173→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
174→	}
175→
176→	ref2, err := repo.GetReference(plumbing.NewBranchReferenceName(branch2), true)
177→	if err != nil {
178→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
179→	}
180→
181→	// Get commit objects
182→	commit1, err := repo.CommitObject(ref1.Hash())
183→	if err != nil {
184→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
185→	}
186→
187→	commit2, err := repo.CommitObject(ref2.Hash())
188→	if err != nil {
189→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
190→	}
191→
192→	// Find common ancestor
193→	mergeBase, err := commit1.MergeBase(commit2)
194→	if err != nil {
195→		return nil, fmt.Errorf("failed to find merge base: %w", err)
196→	}
197→
198→	if len(mergeBase) == 0 {
199→		return nil, errors.New("no common ancestor found")
200→	}
201→
202→	hash := mergeBase[0].Hash
203→	return &hash, nil
204→}
205→
206→// HasUncommittedChanges checks if there are any uncommitted changes in the repository.
207→// This includes staged changes, unstaged changes, and untracked files.
208→// Delegates to gitprovider.Repository which uses the git CLI to respect global gitignore.
209→func HasUncommittedChanges(ctx context.Context) (bool, error) {
210→	repo, err := openProvider(ctx)
211→	if err != nil {
212→		return false, fmt.Errorf("failed to open git repository: %w", err)
213→	}
214→	return repo.HasUncommittedChanges(ctx)
215→}
216→
217→// findNewUntrackedFiles finds files that are newly untracked (not in pre-existing list)
218→func findNewUntrackedFiles(current, preExisting []string) []string {
219→	preExistingSet := make(map[string]bool)
220→	for _, file := range preExisting {
221→		preExistingSet[file] = true
222→	}
223→
224→	var newFiles []string
225→	for _, file := range current {
226→		if !preExistingSet[file] {
227→			newFiles = append(newFiles, file)
228→		}
229→	}
230→	return newFiles
231→}
232→
233→// BranchExistsOnRemote checks if a branch exists on the origin remote.
234→// Returns true if the branch is tracked on origin, false otherwise.
235→func BranchExistsOnRemote(ctx context.Context, branchName string) (bool, error) {
236→	repo, err := openProvider(ctx)
237→	if err != nil {
238→		return false, fmt.Errorf("failed to open git repository: %w", err)
239→	}
240→
241→	// Check for remote reference: refs/remotes/origin/<branchName>
242→	_, err = repo.GetReference(plumbing.NewRemoteReferenceName("origin", branchName), true)
243→	if err != nil {
244→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
245→			return false, nil
246→		}
