	}

	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
	if err := repo.Fetch(ctx, "origin", refSpec, 2*time.Minute); err != nil {
		return fmt.Errorf("failed to fetch branch from origin: %w", err)
